def _check_duplicate_entity_in_model(params):
    models = params.models

    dict_entity = {"Surface": {}, "Volume": {}}
    registry_entity = {"Surface": EntityRegistry(), "Volume": EntityRegistry()}

    if models:
        for model in models:
            if hasattr(model, "entities"):
                for entity in model.entities.stored_entities:
                    _register_single_entity(entity, model.type, registry_entity, dict_entity)

    is_duplicate = any(
        len(model_list) > 1
        for entity_type in dict_entity
        for model_list in dict_entity[entity_type].values()
    )

    if is_duplicate:
        error_msg = ""
        for entity_type in dict_entity.keys():
            for entity_name, model_list in dict_entity[entity_type].items():
                if len(model_list) > 1:
                    model_string = ",".join(f"`{x}`" for x in sorted(set(model_list)))
                    error_msg += (
                        f"{entity_type} entity `{entity_name}` appears "
                        f"multiple times in {model_string} model.\n"
                    )
        raise ValueError(error_msg)

    return params


def _register_single_entity(entity, model_type, registry_entity, dict_entity):
    if isinstance(entity, _SurfaceEntityBase):
        bucket = "Surface"
    elif isinstance(entity, _VolumeEntityBase):
        bucket = "Volume"
    else:
        return

    dict_entity[bucket].setdefault(entity.name, []).append(model_type)
    registry_entity[bucket].register(entity)
